mapper.select:
SELECT num, title, writer,content,hit,elike,reip,bdate,imgn,row_num FROM (
SELECT num, title, writer,content,hit,elike,reip,bdate,imgn, ROW_NUMBER() 
OVER(ORDER BY num desc) AS row_num FROM BOARD 


                AND member_num = #{num}




                        AND writer LIKE '%' || #{searchValue} || '%'


                        AND title LIKE '%' || #{searchValue} || '%'


                        AND content LIKE '%' || #{searchValue} || '%'




) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
